def transform(grid):
    # Crop the four nonzero 3x3 motifs, then place them in reading order.
    colors=[]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v and v not in colors: colors.append(v)
    motifs=[]
    for color in colors:
        cells=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==color]
        r0=min(r for r,c in cells); c0=min(c for r,c in cells)
        motifs.append([[color if grid[r0+i][c0+j]==color else 0 for j in range(3)] for i in range(3)])
    out=[[0]* (3*len(motifs)) for _ in range(3)]
    for k,m in enumerate(motifs):
        for i in range(3):
            for j in range(3): out[i][k*3+j]=m[i][j]
    return out
